/**
 * @summary Registra a certidão emitida (campos "arquivo" e "numero_matricula") e avisa o titular
 */
export const registrarCertidaoEmitida = async (
  id: string,
  registrarCertidaoEmitidaBody: RegistrarCertidaoEmitidaBody,
  options?: Parameters<typeof requisicao>[1],
): Promise<CertidaoResponse> => {
  const formData = new FormData();
  if (registrarCertidaoEmitidaBody.arquivo !== undefined) {
    formData.append(`arquivo`, registrarCertidaoEmitidaBody.arquivo);
  }

  if (registrarCertidaoEmitidaBody.numero_matricula !== undefined) {
    formData.append(`numero_matricula`, registrarCertidaoEmitidaBody.numero_matricula);
  }

  return requisicao<CertidaoResponse>(getRegistrarCertidaoEmitidaUrl(id), {
    ...options,
    method: 'POST',
    body: formData,
  });
};

